using System.IO.Compression;
using System.Text.Json;
using SimplePZMapmaker.Core;
using SimplePZMapmaker.Core.Export;
using SimplePZMapmaker.Web.Services;
public static class ExportJobTests
{
 public static IEnumerable<(string,Action)> Cases(){
  yield return ("native cache hits do not invoke the expensive cell composer and damaged fragments rebuild",()=>InWorkspace(root=>{
   var p=WorldTests.Fixture(1).Maps[0].Project;var directory=Path.Combine(root,"cache");var cache=new NativeSectionCache(directory);var composed=0;bool Write(){using var output=new MemoryStream();using var zip=new ZipArchive(output,ZipArchiveMode.Create,true);return cache.Write(p,zip,"map/",default,null,fragment=>{composed++;foreach(var name in new[]{"100_100.lotheader","world_100_100.lotpack","chunkdata_100_100.bin","maps/biomemap_100_100.png"}){using var cell=fragment.CreateEntry(name).Open();cell.WriteByte(42);}});}Check(!Write()&&Write()&&composed==1,"Cache hit invoked native composition");File.AppendAllText(Directory.EnumerateFiles(directory,"*.zip").Single(),"damaged");Check(!Write()&&composed==2,"Damaged cached fragment was reused");Check(Write()&&composed==2,"Rebuilt fragment was not reusable");
  }));
  yield return ("native section cache skips composition and invalidates terrain, buildings, providers and shared decks",()=>InWorkspace(root=>{
   var p=WorldTests.Fixture(1).Maps[0].Project;var cache=new NativeSectionCache(Path.Combine(root,"cache"));var progress=Export(p,cache);Check(progress.ReusedSections==0,"First section was unexpectedly cached");Check(Export(p,cache).ReusedSections==1,"Unchanged section was recomposed");var key=NativeSectionCache.Key(p);p.Terrain[4]=Terrain.Forest;Check(NativeSectionCache.Key(p)!=key,"Terrain edit did not invalidate section");Check(Export(p,cache).ReusedSections==0,"Terrain edit reused stale cells");key=NativeSectionCache.Key(p);var b=HousingTemplates.Create("village-izba");b.X=40;b.Y=40;p.Buildings.Add(b);Check(NativeSectionCache.Key(p)!=key,"Building edit omitted from key");key=NativeSectionCache.Key(p);p.AssetSources["blends_natural_01_0"]="provider-mod";Check(NativeSectionCache.Key(p)!=key,"Resource ownership omitted from key");key=NativeSectionCache.Key(p);p.SharedInfrastructure=new([new(20,20,1,InfrastructureGeometry.DeckTile)],[]);Check(NativeSectionCache.Key(p)!=key,"JsonIgnored shared deck omitted from key");key=NativeSectionCache.Key(p);p.SharedInfrastructure=new([new(20,20,2,InfrastructureGeometry.DeckTile)],[]);Check(NativeSectionCache.Key(p)!=key,"Shared deck height edit reused stale cells");
  }));
  yield return ("world exports reuse untouched sections but regenerate shared building and bridge changes",()=>InWorkspace(root=>{
   var world=WorldTests.Fixture(2);var cache=new NativeSectionCache(Path.Combine(root,"cache"));NativeExportProgress Run(){NativeExportProgress? last=null;using var output=new MemoryStream();NativeWorldExporter.ExportWithProgress(world,output,new(cache,p=>last=p));return last!;}Check(Run().ReusedSections==0,"Fresh world had cached cells");Check(Run().ReusedSections==2,"Unchanged world recomposed cells");world.Maps[0].Project.Terrain[10]=Terrain.Forest;Check(Run().ReusedSections==1,"Local terrain edit invalidated an unrelated section");var b=HousingTemplates.Create("village-izba");b.X=100*256+250;b.Y=100*256+40;world.Buildings.Add(b);Check(Run().ReusedSections==0,"Cross-boundary building reused stale section cells");world=WorldInfrastructure.Put(world,new(){Id="cached-bridge",Kind="bridge",Level=2,Width=4,Points=[new(100*256+220,100*256+100),new(101*256+30,100*256+100)]});Check(Run().ReusedSections==0,"Shared deck reused stale cells");Check(Run().ReusedSections==2,"Unchanged shared deck was recomposed");world.LinearFeatures[0].Level=3;Check(Run().ReusedSections==0,"Shared deck height reused stale native floors");
  }));
  yield return ("native cache never commits canceled fragments and enforces physical eviction",()=>InWorkspace(root=>{
   var p=WorldTests.Fixture(1).Maps[0].Project;var directory=Path.Combine(root,"cache");var cache=new NativeSectionCache(directory);using var cancel=new CancellationTokenSource();using var output=new MemoryStream();try{NativeMapExporter.ExportWithProgress(p,output,new(cache,progress=>{if(progress.CellsCompleted>0)cancel.Cancel();}),cancel.Token);throw new Exception("Cancellation ignored");}catch(OperationCanceledException){}Check(!Directory.EnumerateFiles(directory).Any(),"Canceled cache fragment survived");Check(Export(p,cache).ReusedSections==0,"Canceled export poisoned cache");var small=new NativeSectionCache(Path.Combine(root,"small"),1);Export(p,small);Check(!Directory.EnumerateFiles(Path.Combine(root,"small"),"*.zip").Any(),"Physical cache budget exceeded");
  }));
  yield return ("native export jobs retain immutable snapshots, progress and reusable section data",()=>InWorkspace(root=>{
   using var store=new ExportJobStore(root);var p=WorldTests.Fixture(1).Maps[0].Project;var name=p.Name;var first=store.StartMap(p);p.Name="Edited after export was queued";var done=Wait(store,first.Id);Check(done.Status=="completed",done.Error??"Export did not finish");Check(done.Progress is {CellsCompleted:1,SectionsCompleted:1,ReusedSections:0},"Job progress lost native cell totals");using(var zip=ZipFile.OpenRead(Path.Combine(root,"work","export-jobs",first.Id+".zip")))using(var source=zip.Entries.Single(e=>e.Name=="project.pzmap.json").Open()){var saved=JsonSerializer.Deserialize<MapProject>(source,NativeMapExporter.JsonOptions)!;Check(saved.Name==name,"Queued job retained mutable project reference");}p.Name=name;var second=Wait(store,store.StartMap(p).Id);Check(second.Progress?.ReusedSections==1,"Queued export recomposed unchanged section");Check(first.SnapshotHash==second.SnapshotHash,"Snapshot hash changed for equal content");Check(File.Exists(Path.Combine(root,"work","export-jobs",first.Id+".json")),"Job metadata not persisted");Check(!Directory.EnumerateFiles(Path.Combine(root,"work","export-jobs"),"*.source").Any(),"Completed snapshot files leaked");
  }));
  yield return ("native job queue rejects overflow and cancellation preserves source",()=>InWorkspace(root=>{
   using var store=new ExportJobStore(root,1,1);var p=MapGenerator.Generate(new(){Kind="blank",Size=1024,Name="Queue fixture"});var first=store.StartMap(p);var deadline=DateTime.UtcNow.AddSeconds(5);while(store.Status(first.Id).Status=="queued"&&DateTime.UtcNow<deadline)Thread.Sleep(5);var queued=store.StartMap(p);try{store.StartMap(p);throw new Exception("Bounded queue accepted overflow");}catch(ArgumentException){}var original=NativeSectionCache.Key(p);store.Cancel(queued.Id);store.Cancel(first.Id);Check(Wait(store,queued.Id).Status=="cancelled","Queued cancellation ignored");Check(Wait(store,first.Id).Status=="cancelled","Running cancellation ignored");Check(NativeSectionCache.Key(p)==original,"Cancellation mutated source project");Check(!Directory.EnumerateFiles(Path.Combine(root,"work","export-jobs"),"*.partial").Any(),"Canceled archive survived");
  }));
  yield return ("restart marks pending exports interrupted and removes only owned temporaries",()=>InWorkspace(root=>{
   var directory=Path.Combine(root,"work","export-jobs");Directory.CreateDirectory(directory);var id=Guid.NewGuid().ToString("N");File.WriteAllText(Path.Combine(directory,id+".json"),JsonSerializer.Serialize(new ExportJobStatus(id,"map","running",new string('a',64),"a",DateTimeOffset.UtcNow),NativeMapExporter.JsonOptions));File.WriteAllText(Path.Combine(directory,id+".partial"),"partial");File.WriteAllText(Path.Combine(directory,id+".source"),"snapshot");var foreign=Path.Combine(directory,"user.partial");File.WriteAllText(foreign,"preserve");using var store=new ExportJobStore(root);Check(store.Status(id).Status=="interrupted","Restart kept a forever-running job");Check(!File.Exists(Path.Combine(directory,id+".partial"))&&!File.Exists(Path.Combine(directory,id+".source")),"Restart left owned partials");Check(File.ReadAllText(foreign)=="preserve","Recovery deleted an unrelated file");
  }));
 }
 static NativeExportProgress Export(MapProject p,NativeSectionCache cache){NativeExportProgress? result=null;using var output=new MemoryStream();NativeMapExporter.ExportWithProgress(p,output,new(cache,p=>result=p));return result!;}
 static ExportJobStatus Wait(ExportJobStore store,string id){var deadline=DateTime.UtcNow.AddSeconds(45);ExportJobStatus status;do{status=store.Status(id);if(status.Status is not ("queued" or "running")){// Finalization may still be removing its owned source file.
    Thread.Sleep(30);return status;}Thread.Sleep(10);}while(DateTime.UtcNow<deadline);throw new Exception("Native export job timed out");}
 static void InWorkspace(Action<string> run){var root=Path.Combine(Environment.GetEnvironmentVariable("PZMAP_WORKSPACE")??Path.GetFullPath("."),"work","export-job-tests",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{run(root);}finally{Directory.Delete(root,true);}}
 static void Check(bool value,string message){if(!value)throw new Exception(message);}
}
